-- ETAPA 17: tenant-scoped risk matrix, preserving methodology versions and reevaluation history.
create table public.processes (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,name text not null check(btrim(name)<>''),code text not null,description text,status text not null default 'active' check(status in ('active','inactive')),created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,code));
create table public.activities (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,process_id uuid not null references public.processes(id) on delete restrict,name text not null check(btrim(name)<>''),description text,status text not null default 'active' check(status in ('active','inactive')),created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,process_id,name));
create table public.risk_tasks (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,activity_id uuid not null references public.activities(id) on delete restrict,name text not null check(btrim(name)<>''),zone_or_location text not null check(btrim(zone_or_location)<>''),is_routine boolean not null default true,description text,status text not null default 'active' check(status in ('active','inactive')),created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,activity_id,name,zone_or_location));
create table public.hazard_catalog (id uuid primary key default gen_random_uuid(),code text not null unique check(code ~ '^[A-Z][A-Z0-9_]{2,80}$'),category text not null check(btrim(category)<>''),name text not null check(btrim(name)<>''),description text,status text not null default 'draft' check(status in ('draft','active','archived')),expert_review_status text not null default 'pending' check(expert_review_status in ('pending','reviewed','rejected')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.risk_identifications (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,risk_task_id uuid not null references public.risk_tasks(id) on delete restrict,hazard_id uuid not null references public.hazard_catalog(id) on delete restrict,description text not null check(btrim(description)<>''),possible_effects text,legal_requirement boolean not null default false,exposed_count integer check(exposed_count is null or exposed_count>=0),worst_consequence text,status text not null default 'active' check(status in ('active','inactive','archived')),created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,risk_task_id,hazard_id));
alter table public.risk_assessments add column risk_identification_id uuid references public.risk_identifications(id) on delete restrict,add column parent_risk_assessment_id uuid references public.risk_assessments(id) on delete restrict,add column deficiency_level numeric(10,2),add column exposure_level numeric(10,2),add column probability_level numeric(10,2),add column consequence_level numeric(10,2),add column risk_level numeric(12,2),add column probability_interpretation text,add column risk_interpretation text,add column acceptability text,add column methodology_snapshot jsonb not null default '{}'::jsonb check(jsonb_typeof(methodology_snapshot)='object');
create table public.risk_controls (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,risk_identification_id uuid not null references public.risk_identifications(id) on delete restrict,control_type text not null check(control_type in ('ELIMINATION','SUBSTITUTION','ENGINEERING','ADMINISTRATIVE','PPE')),description text not null check(btrim(description)<>''),responsible_user_id uuid references auth.users(id) on delete set null,target_date date,status text not null default 'planned' check(status in ('planned','implemented','ineffective','retired')),effectiveness text,evidence_document_version_id uuid references public.document_versions(id) on delete restrict,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index processes_org_status_idx on public.processes(organization_id,status); create index activities_org_process_idx on public.activities(organization_id,process_id); create index risk_tasks_org_activity_idx on public.risk_tasks(organization_id,activity_id); create index risk_identifications_org_task_idx on public.risk_identifications(organization_id,risk_task_id,status); create index risk_assessments_org_identification_idx on public.risk_assessments(organization_id,risk_identification_id,created_at desc); create index risk_controls_org_identification_idx on public.risk_controls(organization_id,risk_identification_id,status);
insert into public.permissions(code,module,action,description) values ('risks.read','risks','read','Consultar matriz de peligros y valoraciones.'),('risks.manage','risks','manage','Gestionar procesos, peligros, controles y valoraciones.'),('risks.validate','risks','validate','Validar valoraciones de riesgo.') on conflict(code) do nothing;
insert into public.role_permissions(role_id,permission_id) select r.id,p.id from public.roles r join public.permissions p on p.code in ('risks.read','risks.manage','risks.validate') where r.code='organization_admin' and r.organization_id is null on conflict do nothing;
create or replace function private.validate_risk_tenant_links() returns trigger language plpgsql security definer set search_path='' as $$ declare linked_org uuid; begin
 if tg_table_name='activities' then select organization_id into linked_org from public.processes where id=new.process_id;
 elsif tg_table_name='risk_tasks' then select organization_id into linked_org from public.activities where id=new.activity_id;
 elsif tg_table_name='risk_identifications' then select organization_id into linked_org from public.risk_tasks where id=new.risk_task_id;
 elsif tg_table_name='risk_assessments' then if new.risk_identification_id is null then return new; end if; select organization_id into linked_org from public.risk_identifications where id=new.risk_identification_id;
 elsif tg_table_name='risk_controls' then select organization_id into linked_org from public.risk_identifications where id=new.risk_identification_id; if new.evidence_document_version_id is not null and not exists(select 1 from public.document_versions where id=new.evidence_document_version_id and organization_id=new.organization_id) then raise exception 'risk control evidence belongs to another organization' using errcode='23514'; end if; end if;
 if linked_org is null or linked_org<>new.organization_id then raise exception 'risk relationship belongs to another organization' using errcode='23514'; end if; return new; end; $$;
create or replace function private.calculate_risk_assessment(p_assessment_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$ declare a public.risk_assessments%rowtype; f record; values_json jsonb; output jsonb:='{}'::jsonb; x numeric; y numeric; result numeric; begin select * into a from public.risk_assessments where id=p_assessment_id for update; if not found then raise exception 'risk assessment not found' using errcode='P0002'; end if; if not private.has_permission(a.organization_id,'risks.manage') then raise exception 'insufficient risk permission' using errcode='42501'; end if; if not exists(select 1 from public.risk_methodology_versions v where v.id=a.risk_methodology_version_id and v.status='approved' and v.expert_review_status='reviewed') then raise exception 'methodology version is not approved' using errcode='23514'; end if; values_json:=a.input_data; for f in select * from public.risk_methodology_formulas where methodology_version_id=a.risk_methodology_version_id and status='approved' and expert_review_status='reviewed' order by code loop if f.interpretation->>'operation'='multiply' then x:=nullif(values_json->>(f.interpretation->'inputs'->>0),'')::numeric; y:=nullif(values_json->>(f.interpretation->'inputs'->>1),'')::numeric; if x is not null and y is not null then result:=x*y; output:=output||jsonb_build_object(f.output_variable_code,result); values_json:=values_json||jsonb_build_object(f.output_variable_code,result); end if; end if; end loop; update public.risk_assessments set result_data=output,methodology_snapshot=(select configuration from public.risk_methodology_versions where id=a.risk_methodology_version_id),probability_level=nullif(output->>'NP','')::numeric,risk_level=nullif(output->>'NR','')::numeric,assessed_at=now(),assessed_by=(select auth.uid()) where id=a.id; return output; end; $$;
revoke all on function private.validate_risk_tenant_links(),private.calculate_risk_assessment(uuid) from public,anon,authenticated,service_role; grant execute on function private.calculate_risk_assessment(uuid) to authenticated;
alter table public.processes enable row level security; alter table public.activities enable row level security; alter table public.risk_tasks enable row level security; alter table public.hazard_catalog enable row level security; alter table public.risk_identifications enable row level security; alter table public.risk_controls enable row level security;
grant select,insert,update on public.processes,public.activities,public.risk_tasks,public.risk_identifications,public.risk_controls to authenticated; grant select on public.hazard_catalog to authenticated;
create policy processes_read on public.processes for select to authenticated using((select private.has_permission(organization_id,'risks.read'))); create policy processes_write on public.processes for all to authenticated using((select private.has_permission(organization_id,'risks.manage'))) with check((select private.has_permission(organization_id,'risks.manage'))); create policy activities_read on public.activities for select to authenticated using((select private.has_permission(organization_id,'risks.read'))); create policy activities_write on public.activities for all to authenticated using((select private.has_permission(organization_id,'risks.manage'))) with check((select private.has_permission(organization_id,'risks.manage'))); create policy risk_tasks_read on public.risk_tasks for select to authenticated using((select private.has_permission(organization_id,'risks.read'))); create policy risk_tasks_write on public.risk_tasks for all to authenticated using((select private.has_permission(organization_id,'risks.manage'))) with check((select private.has_permission(organization_id,'risks.manage'))); create policy hazard_catalog_read on public.hazard_catalog for select to authenticated using((select auth.uid()) is not null); create policy risk_identifications_read on public.risk_identifications for select to authenticated using((select private.has_permission(organization_id,'risks.read'))); create policy risk_identifications_write on public.risk_identifications for all to authenticated using((select private.has_permission(organization_id,'risks.manage'))) with check((select private.has_permission(organization_id,'risks.manage'))); create policy risk_controls_read on public.risk_controls for select to authenticated using((select private.has_permission(organization_id,'risks.read'))); create policy risk_controls_write on public.risk_controls for all to authenticated using((select private.has_permission(organization_id,'risks.manage'))) with check((select private.has_permission(organization_id,'risks.manage')));
create trigger activities_validate_risk_links before insert or update on public.activities for each row execute function private.validate_risk_tenant_links(); create trigger risk_tasks_validate_links before insert or update on public.risk_tasks for each row execute function private.validate_risk_tenant_links(); create trigger risk_identifications_validate_links before insert or update on public.risk_identifications for each row execute function private.validate_risk_tenant_links(); create trigger risk_assessments_validate_links before insert or update on public.risk_assessments for each row execute function private.validate_risk_tenant_links(); create trigger risk_controls_validate_links before insert or update on public.risk_controls for each row execute function private.validate_risk_tenant_links();
create trigger processes_updated before update on public.processes for each row execute function private.set_updated_at(); create trigger activities_updated before update on public.activities for each row execute function private.set_updated_at(); create trigger risk_tasks_updated before update on public.risk_tasks for each row execute function private.set_updated_at(); create trigger risk_identifications_updated before update on public.risk_identifications for each row execute function private.set_updated_at(); create trigger risk_controls_updated before update on public.risk_controls for each row execute function private.set_updated_at(); create trigger risk_controls_capture_audit after insert or update on public.risk_controls for each row execute function private.capture_core_audit();
notify pgrst,'reload schema';
